//
// Replays facts recorded NATIVELY on Apple silicon
// (tests/fixtures/aarch64_nzcv_silicon_truth.json, regenerated by
// gen_aarch64_nzcv_silicon_truth.sh) against trust-cg's in-house models:
//
//   * the integer NZCV producers in `nzcv.rs` — ADDS, SUBS, CMP (register and
//     #imm12, through BOTH the full-adder `encode_cmp` the comparison proofs
//     use and the AddWithCarry transcription), ADCS/SBCS with carry-in 0 and 1,
//     TST (register and bitmask immediate), and the ADC/SBC values with NZCV
//     preserved;
//   * the conditional-select decoder/model (`aarch64_csel_semantics`) for
//     CSEL/CSINC/CSINV/CSNEG at W and X, all 16 conditions and all 16 incoming
//     NZCV values, concretely and symbolically;
//   * the integer-only FCMP model and the registered FCMP packed-NZCV and
//     FCMP -> CSET obligations (`aarch64_flag_consumer_proofs`), plus the
//     per-flag FCMP facts recorded on an Apple M4 Pro in the Clean chip file
//     (tests/fixtures/aarch64_fp_silicon_truth.json).
//
// W-form operands in the fixture carry nonzero upper halves, so a model that
// reads bits 63:32 of a W operand mismatches. Non-vacuity tests below show a
// deliberately wrong model mismatches at least one fact of each family.
//
// This is regression evidence for one host CPU over a finite boundary grid —
// not a proof, and not a statement about other AArch64 implementations.

use std::collections::HashMap;

use serde_json::Value;

use trust_cg_verify::aarch64_csel_semantics::{
    DecodedConditionalSelect, RegisterState, SymbolicRegisterState,
};
use trust_cg_verify::aarch64_flag_consumer_proofs::{
    CONDITION_NAMES, fcmp_cset_obligation, fcmp_packed_obligation, fp_compare_relation,
};
use trust_cg_verify::nzcv::{
    NzcvFlags, encode_adc, encode_adcs, encode_adds, encode_cmp, encode_sbc, encode_sbcs,
    encode_subs, encode_tst, pack_nzcv,
};
use trust_cg_verify::smt::{EvalEnv, EvalResult, SmtExpr};

const FIXTURE: &str = include_str!("fixtures/aarch64_nzcv_silicon_truth.json");
const FP_FIXTURE: &str = include_str!("fixtures/aarch64_fp_silicon_truth.json");

#[derive(Debug, Clone)]
struct Fact {
    op: String,
    width: u32,
    cond: Option<u8>,
    a: u64,
    b: u64,
    nzcv_in: u64,
    result: Option<u64>,
    nzcv: u64,
}

fn hex(value: &Value) -> u64 {
    let text = value.as_str().expect("hex string");
    u64::from_str_radix(text.trim_start_matches("0x"), 16).expect("hex literal")
}

/// Environment override naming ANOTHER host's recording (for example one made
/// on the Linux AArch64 host with `gen_aarch64_nzcv_silicon_truth.sh OUT`), to
/// replay instead of the committed Apple fixture. The replay counts are fixed
/// by the harness grid, so they hold for any host.
const FIXTURE_OVERRIDE: &str = "TCG_NZCV_SILICON_TRUTH";

fn fixture_text() -> (String, bool) {
    match std::env::var_os(FIXTURE_OVERRIDE) {
        Some(path) => (
            std::fs::read_to_string(&path).unwrap_or_else(|error| {
                panic!("{FIXTURE_OVERRIDE}={}: {error}", path.to_string_lossy())
            }),
            true,
        ),
        None => (FIXTURE.to_string(), false),
    }
}

fn load() -> (Value, Vec<Fact>) {
    let (text, _) = fixture_text();
    let doc: Value = serde_json::from_str(&text).expect("fixture is valid JSON");
    let facts = doc["facts"]
        .as_array()
        .expect("facts array")
        .iter()
        .map(|fact| Fact {
            op: fact["op"].as_str().expect("op").to_string(),
            width: fact["width"].as_u64().expect("width") as u32,
            cond: fact.get("cond").and_then(Value::as_u64).map(|c| c as u8),
            a: hex(&fact["a"]),
            b: hex(&fact["b"]),
            nzcv_in: fact["nzcv_in"].as_u64().expect("nzcv_in"),
            result: (!fact["result"].is_null()).then(|| hex(&fact["result"])),
            nzcv: fact["nzcv"].as_u64().expect("nzcv"),
        })
        .collect();
    (doc, facts)
}

fn mask(width: u32) -> u64 {
    if width == 64 {
        u64::MAX
    } else {
        (1u64 << width) - 1
    }
}

fn leaf(value: u64, width: u32) -> SmtExpr {
    SmtExpr::bv_const(value & mask(width), width)
}

fn bv(expr: &SmtExpr) -> u64 {
    match expr.try_eval(&EvalEnv::default()) {
        Ok(EvalResult::Bv(value)) => value,
        other => panic!("expected a bitvector, got {other:?}"),
    }
}

fn packed(flags: &NzcvFlags) -> u64 {
    bv(&pack_nzcv(flags))
}

/// The value a W/X destination write leaves in the 64-bit register.
fn register_value(value: u64, width: u32) -> u64 {
    value & mask(width)
}

/// Model result and flags for an integer producer fact, or `None` for a
/// select/FCMP fact.
fn integer_model(fact: &Fact) -> Option<(Option<u64>, u64)> {
    let w = fact.width;
    let (a, b) = (leaf(fact.a, w), leaf(fact.b, w));
    let carry = SmtExpr::bv_const((fact.nzcv_in >> 1) & 1, 1);
    Some(match fact.op.as_str() {
        "adds" => {
            let (r, f) = encode_adds(a, b, w);
            (Some(bv(&r)), packed(&f))
        }
        "subs" => {
            let (r, f) = encode_subs(a, b, w);
            (Some(bv(&r)), packed(&f))
        }
        "cmp" | "cmp_imm" => {
            let full_adder = packed(&encode_cmp(a.clone(), b.clone(), w));
            let add_with_carry = packed(&encode_subs(a, b, w).1);
            assert_eq!(
                full_adder, add_with_carry,
                "CMP models disagree on {fact:?}"
            );
            (None, full_adder)
        }
        "tst" | "tst_imm" => (None, packed(&encode_tst(a, b, w))),
        "adcs" => {
            let (r, f) = encode_adcs(a, b, carry, w);
            (Some(bv(&r)), packed(&f))
        }
        "sbcs" => {
            let (r, f) = encode_sbcs(a, b, carry, w);
            (Some(bv(&r)), packed(&f))
        }
        "adc" => (Some(bv(&encode_adc(a, b, carry, w))), fact.nzcv_in),
        "sbc" => (Some(bv(&encode_sbc(a, b, carry, w))), fact.nzcv_in),
        _ => return None,
    })
}

fn select_word(op: &str, width: u32, cond: u8) -> u32 {
    let base: u32 = match op {
        "csel" => 0x1A80_0000,
        "csinc" => 0x1A80_0400,
        "csinv" => 0x5A80_0000,
        "csneg" => 0x5A80_0400,
        other => panic!("not a select: {other}"),
    };
    // Rd = 0, Rn = 1, Rm = 2.
    base | (u32::from(width == 64) << 31) | (2 << 16) | (u32::from(cond) << 12) | (1 << 5)
}

fn select_state(fact: &Fact) -> RegisterState {
    let mut x: [u64; 31] = std::array::from_fn(|index| 0x5a5a_0000_0000_0000 | index as u64);
    x[1] = fact.a;
    x[2] = fact.b;
    RegisterState {
        x,
        sp: 0x7fff_0000,
        nzcv: fact.nzcv_in as u8,
    }
}

#[test]
fn fixture_header_and_accounting_are_consistent() {
    let (doc, facts) = load();
    let header = &doc["_header"];
    let cpu = header["recorded_on_cpu"].as_str().unwrap_or_default();
    if fixture_text().1 {
        // Another host's recording must still name the CPU it ran on.
        assert!(
            !cpu.trim().is_empty() && cpu != "unknown",
            "the recording must name the CPU it ran on: {header}"
        );
    } else {
        assert!(
            cpu.starts_with("Apple"),
            "the committed fixture must record the Apple silicon it ran on: {header}"
        );
    }
    let mut per_op: HashMap<String, u64> = HashMap::new();
    for fact in &facts {
        *per_op.entry(fact.op.clone()).or_default() += 1;
        assert!(fact.nzcv <= 15 && fact.nzcv_in <= 15, "{fact:?}");
        assert!(matches!(fact.width, 32 | 64), "{fact:?}");
    }
    let accounting = &doc["_accounting"];
    assert_eq!(accounting["facts"].as_u64(), Some(facts.len() as u64));
    for (op, count) in accounting["per_op"].as_object().expect("per_op") {
        assert_eq!(per_op.get(op).copied(), count.as_u64(), "{op}");
    }
    // Every producer, carry reader, select and FCMP family is present.
    for op in [
        "adds", "subs", "cmp", "cmp_imm", "tst", "tst_imm", "adcs", "sbcs", "adc", "sbc", "csel",
        "csinc", "csinv", "csneg", "fcmp",
    ] {
        assert!(per_op.get(op).copied().unwrap_or(0) > 0, "{op} missing");
    }
    // W-form operands really carry nonzero upper halves.
    assert!(facts.iter().any(|f| f.width == 32 && f.a >> 32 != 0));
}

#[test]
fn integer_nzcv_producers_match_native_silicon() {
    let (_, facts) = load();
    let mut replayed = 0;
    for fact in &facts {
        let Some((result, nzcv)) = integer_model(fact) else {
            continue;
        };
        assert_eq!(nzcv, fact.nzcv, "NZCV mismatch on {fact:?}");
        match (result, fact.result) {
            (Some(model), Some(silicon)) => {
                assert_eq!(
                    register_value(model, fact.width),
                    silicon,
                    "result mismatch on {fact:?}"
                );
                if fact.width == 32 {
                    assert_eq!(silicon >> 32, 0, "W write must clear Xd[63:32]: {fact:?}");
                }
            }
            (None, None) => {}
            other => panic!("result presence mismatch {other:?} on {fact:?}"),
        }
        replayed += 1;
    }
    // 30x30 pairs x {ADDS,SUBS,CMP,TST} x 2 widths, x2 carries x {ADCS,SBCS,ADC,SBC}
    // x 2 widths, plus 12 immediate forms x 30 values.
    assert_eq!(replayed, 7200 + 14_400 + 360);
}

#[test]
fn conditional_selects_match_native_silicon_concretely_and_symbolically() {
    let (_, facts) = load();
    let symbolic = SymbolicRegisterState::variables();
    let mut replayed = 0;
    for fact in facts.iter().filter(|f| f.op.starts_with("cs")) {
        let cond = fact.cond.expect("select facts carry a condition");
        let decoded = DecodedConditionalSelect::decode(select_word(&fact.op, fact.width, cond))
            .expect("constructed select word decodes");
        let before = select_state(fact);
        let after = decoded.execute(&before).expect("valid state");
        assert_eq!(Some(after.x[0]), fact.result, "{fact:?}");
        assert_eq!(
            fact.nzcv, fact.nzcv_in,
            "selects must preserve NZCV: {fact:?}"
        );
        // The symbolic model agrees with silicon at this state.
        let value = decoded.execute_symbolic(&symbolic);
        let mut env = EvalEnv::default();
        for (index, register) in before.x.iter().enumerate() {
            env.insert(format!("x{index}"), *register);
        }
        env.insert("sp".to_string(), before.sp);
        env.insert("nzcv".to_string(), fact.nzcv_in);
        assert_eq!(
            value.register(0).expect("X0").try_eval(&env).ok(),
            Some(EvalResult::Bv(fact.result.expect("select result"))),
            "{fact:?}"
        );
        replayed += 1;
    }
    assert_eq!(replayed, 4 * 2 * 16 * 16 * 4);
}

#[test]
fn fcmp_models_and_registered_obligations_match_native_silicon() {
    let (_, facts) = load();
    let mut replayed = 0;
    for fact in facts.iter().filter(|f| f.op == "fcmp") {
        let w = fact.width;
        let relation = fp_compare_relation(&leaf(fact.a, w), &leaf(fact.b, w), w).unwrap();
        assert_eq!(bv(&relation.packed()), fact.nzcv, "{fact:?}");
        assert_eq!(packed(&relation.flags()), fact.nzcv, "{fact:?}");
        let mut env = EvalEnv::default();
        env.insert("a_bits".to_string(), fact.a);
        env.insert("b_bits".to_string(), fact.b);
        // Both sides of the registered packed obligation equal silicon NZCV.
        let obligation = fcmp_packed_obligation(w).unwrap();
        for side in [&obligation.trust_ir_expr, &obligation.aarch64_expr] {
            assert_eq!(
                side.try_eval(&env).ok(),
                Some(EvalResult::Bv(fact.nzcv)),
                "{fact:?}"
            );
        }
        // Every FCMP -> CSET obligation equals ConditionHolds on silicon NZCV.
        for cc in 0..14u8 {
            let want = u64::from(
                trust_cg_verify::aarch64_csel_semantics::condition_holds(cc, fact.nzcv as u8)
                    .unwrap(),
            );
            let obligation = fcmp_cset_obligation(w, cc).unwrap();
            for side in [&obligation.trust_ir_expr, &obligation.aarch64_expr] {
                assert_eq!(
                    side.try_eval(&env).ok(),
                    Some(EvalResult::Bv(want)),
                    "{} on {fact:?}",
                    CONDITION_NAMES[usize::from(cc)]
                );
            }
        }
        assert_eq!(fact.result, None);
        replayed += 1;
    }
    assert_eq!(replayed, 22 * 22 * 2);
}

#[test]
fn fcmp_model_matches_the_m4_pro_per_flag_chip_facts() {
    let doc: Value = serde_json::from_str(FP_FIXTURE).expect("FP fixture is valid JSON");
    let mut replayed = 0;
    for fact in doc["facts"].as_array().expect("facts") {
        let op = fact["op"].as_str().expect("op");
        let flag = match op {
            "fcmpN" => 3,
            "fcmpZ" => 2,
            "fcmpC" => 1,
            "fcmpV" => 0,
            _ => continue,
        };
        let widths = fact["in_widths"].as_array().expect("in_widths");
        let w = widths[0].as_u64().expect("width") as u32;
        let operands = fact["operands"].as_array().expect("operands");
        let (a, b) = (
            operands[0].as_u64().expect("a"),
            operands[1].as_u64().expect("b"),
        );
        let relation = fp_compare_relation(&leaf(a, w), &leaf(b, w), w).unwrap();
        let nzcv = bv(&relation.packed());
        assert_eq!(
            (nzcv >> flag) & 1,
            fact["result"].as_u64().expect("result"),
            "{op} w{w} {a:#x} {b:#x}"
        );
        replayed += 1;
    }
    assert_eq!(replayed, 1360);
}

// ---------------------------------------------------------------------------
// Non-vacuity: a wrong model mismatches silicon
// ---------------------------------------------------------------------------

#[test]
fn a_borrow_convention_carry_mismatches_silicon() {
    // x86-style SUB carry: C = borrow (a <u b), the inverse of the Arm C flag.
    let (_, facts) = load();
    let mismatches = facts
        .iter()
        .filter(|f| f.op == "cmp")
        .filter(|f| {
            let m = mask(f.width);
            let borrow = u64::from((f.a & m) < (f.b & m));
            (f.nzcv >> 1) & 1 != borrow
        })
        .count();
    assert_eq!(
        mismatches,
        facts.iter().filter(|f| f.op == "cmp").count(),
        "silicon C is NOT-borrow on every CMP fact"
    );
}

#[test]
fn reading_w_operand_upper_halves_mismatches_silicon() {
    let (_, facts) = load();
    let wrong = facts
        .iter()
        .filter(|f| f.op == "adds" && f.width == 32)
        .filter(|f| {
            // Treat the 64-bit register values as the operands.
            let (_, flags) = encode_adds(leaf(f.a, 64), leaf(f.b, 64), 64);
            packed(&flags) != f.nzcv
        })
        .count();
    assert!(wrong > 0, "the W-form facts must distinguish a 64-bit read");
}

#[test]
fn x86_unordered_fcmp_flags_mismatch_silicon() {
    let (_, facts) = load();
    let wrong = facts
        .iter()
        .filter(|f| f.op == "fcmp")
        .filter(|f| {
            let w = f.width;
            let relation = fp_compare_relation(&leaf(f.a, w), &leaf(f.b, w), w).unwrap();
            let unordered = matches!(
                relation.unordered.try_eval(&EvalEnv::default()),
                Ok(EvalResult::Bool(true))
            );
            // UCOMIS reports unordered as ZF = CF = 1: NZCV 0110.
            unordered && f.nzcv == 0b0110
        })
        .count();
    let unordered_facts = facts
        .iter()
        .filter(|f| f.op == "fcmp" && f.nzcv == 0b0011)
        .count();
    assert_eq!(wrong, 0);
    assert!(unordered_facts > 0, "the grid must reach unordered results");
}

#[test]
fn never_true_nv_mismatches_silicon() {
    // NV (15) is architecturally always true for CSEL; a model treating it as
    // the complement of AL mismatches.
    let (_, facts) = load();
    let nv_facts: Vec<&Fact> = facts
        .iter()
        .filter(|f| f.op == "csel" && f.cond == Some(15))
        .collect();
    assert!(!nv_facts.is_empty());
    assert!(
        nv_facts
            .iter()
            .all(|f| f.result == Some(register_value(f.a, f.width))),
        "CSEL NV must select the first operand on silicon"
    );
}
